    const copy=titles[view]||titles.today; $('#page-title').textContent=copy[0]; $('#page-subtitle').textContent=copy[1]; $('#list-title').textContent=copy[2];
    $$('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
    $('#today-count').textContent=data.tasks.filter(t=>isOpen(t)&&t.planned===today).length||''; $('#inbox-count').textContent=data.tasks.filter(t=>isOpen(t)&&!t.planned&&!t.due&&t.status!=='waiting').length||'';
    const planned=data.tasks.filter(t=>isOpen(t)&&t.planned===today).reduce((s,t)=>s+(Number(t.estimate)||0),0); const effective=Math.round(data.available*(data.buffer?.8:1));
    $('#plan-load').textContent=`${planned} min planned${data.available?` · ${effective} min available`:''}`; $('#meter-fill').style.width=`${Math.min(100,effective?planned/effective*100:planned?100:0)}%`; $('#meter-fill').style.background=planned>effective?'#e3b68c':'#dbe8d2';
    $('#plan-hint').textContent=planned>effective?`That’s ${planned-effective} min over your plan. You can move a task or adjust your available time.`:`${data.buffer?'A 20% buffer is set aside for the unexpected.':'No buffer set.'} Add, move, or change tasks whenever you need.`;
    const profileView=view==='profile';$('#add-task').classList.toggle('hidden',profileView);$('#list-toolbar').classList.toggle('hidden',profileView);$('#profile-view').classList.toggle('hidden',!profileView);
    const categoryView=['projects','areas','resources'].includes(view); $('#category-tools').classList.toggle('hidden',!categoryView); $('#category-add').textContent=view==='projects'?'＋ Add a project':view==='areas'?'＋ Add an area':'＋ Save a resource'; $('#show-archived').checked=!!data.showArchived;
    if(categoryView||profileView)$('#filter-row').classList.add('hidden');
    $('#plan-card').classList.toggle('hidden',view!=='today'); $('#sort-select').parentElement.classList.toggle('hidden',categoryView||profileView||view==='project-tasks'||view==='area-tasks'); $('#filter-toggle').classList.toggle('hidden',categoryView||profileView||view==='project-tasks'||view==='area-tasks');
