    const query=searchTerm.toLowerCase().trim(); let tasks=data.tasks.filter(matchesView).filter(t=>!query||[t.title,t.action,t.notes,t.blocker,projectName(t.project),areaName(t.area)].join(' ').toLowerCase().includes(query));
