    const sort=$('#sort-select').value; tasks.sort((a,b)=> sort==='due'?((a.due||'9999').localeCompare(b.due||'9999')):sort==='priority'?(Number(a.priority||3)-Number(b.priority||3)):((a.planned||'9999').localeCompare(b.planned||'9999')));
